  v_bad text;
  v_lv int; v_pos int;
begin
  drop table if exists _m, _t;
  create temp table _m on commit drop as
    select split_part(x, ':', 1)::bigint as lesson, split_part(x, ':', 2)::int as rnk, split_part(x, ':', 3)::int as seq
      from unnest(string_to_array(v_map, ',')) x;

  if (select count(*) from _m) <> 894 or (select count(distinct lesson) from _m) <> 894 then
    raise exception 'الخريطة ليست ٨٩٤ درساً فريداً';
  end if;
  -- المكتبةُ اليوم هي ما قيس: لا كتابَ خارج الخريطة ولا كتابَ فيها ليس في المكتبة
  select string_agg(x, ' · ') into v_bad from (
    select 'في المكتبة وليس في الخريطة: ' || string_agg(l.id::text, ',') x from lessons l
     where l.subject_id = 7 and l.archived_at is null and not exists (select 1 from _m m where m.lesson = l.id) having count(*) > 0
    union all
    select 'في الخريطة وليس في المكتبة: ' || string_agg(m.lesson::text, ',') from _m m
     where not exists (select 1 from lessons l where l.id = m.lesson and l.subject_id = 7 and l.archived_at is null) having count(*) > 0
  ) g;
  if v_bad is not null then
    raise exception 'تغيّرت المكتبةُ منذ القياس — لا يُنقل شيء: %', v_bad;
  end if;

  -- المقرَّرُ الهدف: المستوى الجديد في سلّم الدرس نفسِه × طبقةُ مقرَّره الحاليّ
  create temp table _t on commit drop as
    select m.lesson, m.seq, l.course_id as from_course, l.level_id as from_level, l.position as from_pos, ol.rank as from_rank,
           nl.id as level_id, nc.id as course_id, l.published, l.author_key
      from _m m
      join lessons l  on l.id = m.lesson
      join levels ol  on ol.id = l.level_id
      join courses oc on oc.id = l.course_id
      left join levels nl  on nl.scale_id = ol.scale_id and nl.rank = m.rnk
      left join courses nc on nc.subject_id = l.subject_id and nc.level_id = nl.id and nc.tier = oc.tier;

  select string_agg(x, ' · ') into v_bad from (
    select 'بلا مقرَّرٍ هدف: ' || string_agg(lesson::text, ',') x from _t where course_id is null having count(*) > 0
    union all select 'منشورٌ يُنقل: ' || string_agg(lesson::text, ',') from _t where published and course_id <> from_course having count(*) > 0
    union all select 'مؤلَّفٌ يُنقل: ' || string_agg(lesson::text, ',') from _t where seq = 0 and course_id <> from_course having count(*) > 0
    union all select 'مفتاحُ تأليفٍ يتكرّر في مقرَّرٍ واحد: ' || string_agg(author_key, ',') from (
        select course_id, author_key from _t where author_key is not null group by 1, 2 having count(*) > 1) d having count(*) > 0
    union all select 'مفتاحُ تأليفٍ يتكرّر في المكتبة (قد يتصادم في أثناء النقل): ' || string_agg(author_key, ',') from (
        select author_key from _t where author_key is not null group by 1 having count(*) > 1) d having count(*) > 0
  ) g;
  if v_bad is not null then
    raise exception 'لا يُنقل شيء: %', v_bad;
  end if;

  -- الموضعُ في الرفّ: المؤلَّفُ أوّلاً بترتيبه الحاليّ، ثمّ المنقولُ بتسلسله
  with todo as (
    select t.lesson, t.level_id, t.course_id,
           row_number() over (partition by t.course_id
                              order by (t.seq = 0) desc, case when t.seq = 0 then t.from_pos end, t.seq, t.lesson) as pos
      from _t t
  ), upd as (
    update lessons l
       set level_id = d.level_id, course_id = d.course_id, position = d.pos
      from todo d
     where l.id = d.lesson
       and (l.level_id, l.course_id, l.position) is distinct from (d.level_id, d.course_id, d.pos::int)
    returning l.id
  )
  select count(*) filter (where t.course_id <> t.from_course), count(*) into v_lv, v_pos
    from upd u join _t t on t.lesson = u.id;
  perform set_config('relevel.moved', v_lv || ' level · ' || v_pos || ' rows', true);
end $$;

insert into public.sql_log (n, title, applied_at)
values ('240', 'إعادةُ تسكين مكتبة بيان على صعوبة اللغة — ٧٧١ كتاباً ينتقل، وكلُّ رفٍّ يُرتَّب من الأقصر إلى الأطول', now())
on conflict (n) do update set applied_at = now();
